CREATE TYPE "CouponType" AS ENUM ('FIXED','PERCENTAGE');
ALTER TABLE "ProductVariant" ADD COLUMN "taxProfileId" UUID, ADD COLUMN "hsnCode" TEXT;
ALTER TABLE "Order" ADD COLUMN "taxablePaise" INTEGER NOT NULL DEFAULT 0,ADD COLUMN "taxPaise" INTEGER NOT NULL DEFAULT 0,ADD COLUMN "cgstPaise" INTEGER NOT NULL DEFAULT 0,ADD COLUMN "sgstPaise" INTEGER NOT NULL DEFAULT 0,ADD COLUMN "igstPaise" INTEGER NOT NULL DEFAULT 0,ADD COLUMN "couponCode" TEXT;
ALTER TABLE "Order" ADD CONSTRAINT "Order_tax_values_check" CHECK ("taxablePaise">=0 AND "taxPaise">=0 AND "cgstPaise">=0 AND "sgstPaise">=0 AND "igstPaise">=0);
CREATE TABLE "TaxProfile"("id" UUID NOT NULL,"name" TEXT NOT NULL,"code" TEXT NOT NULL,"rateBasisPoints" INTEGER NOT NULL,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "TaxProfile_pkey" PRIMARY KEY("id"),CONSTRAINT "TaxProfile_rate_check" CHECK("rateBasisPoints">=0 AND "rateBasisPoints"<=10000));CREATE UNIQUE INDEX "TaxProfile_code_key" ON "TaxProfile"("code");ALTER TABLE "ProductVariant" ADD CONSTRAINT "ProductVariant_taxProfileId_fkey" FOREIGN KEY("taxProfileId") REFERENCES "TaxProfile"("id") ON DELETE SET NULL ON UPDATE CASCADE;CREATE INDEX "ProductVariant_taxProfileId_idx" ON "ProductVariant"("taxProfileId");
CREATE TABLE "Coupon"("id" UUID NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"type" "CouponType" NOT NULL,"value" INTEGER NOT NULL,"maxDiscountPaise" INTEGER,"minimumSubtotalPaise" INTEGER NOT NULL DEFAULT 0,"usageLimit" INTEGER,"usageLimitPerUser" INTEGER,"startsAt" TIMESTAMP(3),"expiresAt" TIMESTAMP(3),"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Coupon_pkey" PRIMARY KEY("id"),CONSTRAINT "Coupon_values_check" CHECK("value">=0 AND "minimumSubtotalPaise">=0 AND ("maxDiscountPaise" IS NULL OR "maxDiscountPaise">=0) AND ("usageLimit" IS NULL OR "usageLimit">0) AND ("usageLimitPerUser" IS NULL OR "usageLimitPerUser">0)));CREATE UNIQUE INDEX "Coupon_code_key" ON "Coupon"("code");CREATE INDEX "Coupon_isActive_startsAt_expiresAt_idx" ON "Coupon"("isActive","startsAt","expiresAt");
CREATE TABLE "CouponRedemption"("id" UUID NOT NULL,"couponId" UUID NOT NULL,"userId" UUID NOT NULL,"orderId" UUID NOT NULL,"discountPaise" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CouponRedemption_pkey" PRIMARY KEY("id"),CONSTRAINT "CouponRedemption_couponId_fkey" FOREIGN KEY("couponId") REFERENCES "Coupon"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "CouponRedemption_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "CouponRedemption_orderId_fkey" FOREIGN KEY("orderId") REFERENCES "Order"("id") ON DELETE RESTRICT ON UPDATE CASCADE);CREATE UNIQUE INDEX "CouponRedemption_orderId_key" ON "CouponRedemption"("orderId");CREATE INDEX "CouponRedemption_couponId_idx" ON "CouponRedemption"("couponId");CREATE INDEX "CouponRedemption_userId_idx" ON "CouponRedemption"("userId");CREATE INDEX "CouponRedemption_orderId_idx" ON "CouponRedemption"("orderId");CREATE INDEX "CouponRedemption_createdAt_idx" ON "CouponRedemption"("createdAt");CREATE INDEX "CouponRedemption_couponId_userId_idx" ON "CouponRedemption"("couponId","userId");
CREATE TABLE "Invoice"("id" UUID NOT NULL,"orderId" UUID NOT NULL,"invoiceNumber" TEXT NOT NULL,"issuedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"sellerSnapshot" JSONB NOT NULL,"buyerSnapshot" JSONB NOT NULL,"financialSnapshot" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Invoice_pkey" PRIMARY KEY("id"),CONSTRAINT "Invoice_orderId_fkey" FOREIGN KEY("orderId") REFERENCES "Order"("id") ON DELETE RESTRICT ON UPDATE CASCADE);CREATE UNIQUE INDEX "Invoice_orderId_key" ON "Invoice"("orderId");CREATE UNIQUE INDEX "Invoice_invoiceNumber_key" ON "Invoice"("invoiceNumber");CREATE INDEX "Invoice_issuedAt_idx" ON "Invoice"("issuedAt");
